Script:
DetailedNav = {
	init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=DetailedNav]");
		var query = "core/Page?$filter=AppId eq " + session.app.Id + " and ParentId eq " + session.page.PageId + "&$expand=PageInfo,Pages($expand=PageInfo,Pages($expand=PageInfo))";
		await api.get(query).then(function(pages) {
			var itemsPerRow = 3;
			var pages = pages.value.filter(function(item) {
				return item.ShowOnMenus;
			}).sort(function(i) {
				return i.Order;
			});
			console.log(pages);
			for(var i = 0; i < pages.length; i += itemsPerRow) {
				var thisRow = pages.slice(i, i + itemsPerRow);
				console.log(thisRow);
				DetailedNav.generateRow(thisRow, $("nav", container));
			}

			// for(var i in pages.value.sort(function(i) { return i.Order; })) {
			// 	if(pages.value[i].ShowOnMenus) {
			// 		DetailedNav.createItem(pages.value[i], container);
			// 	}
			// } 
		});
	},

	generateRow(items, container) {
		if(items.length == 0)
			return;

		var row = $('<div class="row"></div>');
		for(var i = 0; i < items.length; i++) {
			var item = items[i];
			console.log(item);
			if(item.Path == null)
				item.Path = '';

			var itemElement = $('<div class="col-md-4"></div>');
			itemElement.append($('<a href="/' + item.Path + '">' + DetailedNav.titleOf(item) + '</a>'));
			itemElement.append($('<p>' + DetailedNav.descriptionOf(item) + '</p>'));
			row.append(itemElement);
		}
		container.append(row);
	},

	createItem: function(page, parentElement) {
		if(page.Path === null) { page.Path = ""; }

		parentElement.append($("<li data-id='" + page.Id + "'></li>"));
		var thisNode = $("li[data-id=" + page.Id + "]", parentElement);
		thisNode.append("<a href='/" + page.Path + "'>" + DetailedNav.titleOf(page) + "</a><p>" + DetailedNav.descriptionOf(page) + "</p>");
	},

	itemClass: function(page) {
		if(session.page.PageId == page.Id) { return "item current"; }
		return "item";
	},

	titleOf: function(page) {
		var culture = $("html").attr("lang");
		for(var i in page.PageInfo) {  
			if(page.PageInfo[i].CultureId === culture)
				return page.PageInfo[i].Title;
		}

		for(var i in page.PageInfo) {  
			if(page.PageInfo[i].CultureId === "")
				return page.PageInfo[i].Title;
		}

		return "unknown";
	},

    descriptionOf: function(page) {
		var culture = $("html").attr("lang");
		for(var i in page.PageInfo) {  
			if(page.PageInfo[i].CultureId === culture)
				return page.PageInfo[i].Description;
		}

		for(var i in page.PageInfo) {  
			if(page.PageInfo[i].CultureId === "")
				return page.PageInfo[i].Description;
		}

		return "unknown";
	}
};
